import bpy, sys, types, importlib.util, pathlib, json, traceback, hashlib
root=pathlib.Path('/home/oae/Рабочий стол/skill/.cache/RBX_Toolbox')
out=pathlib.Path('/tmp/roblox-rbx-toolbox-audit')
# Disable all HTTP. Only reviewed local operators are imported; no upstream startup/installer.
requests=types.ModuleType('requests')
class DisabledNetwork(Exception): pass
requests.ConnectionError=DisabledNetwork;requests.Timeout=DisabledNetwork
requests.get=lambda *a,**k: (_ for _ in ()).throw(DisabledNetwork('Network disabled during scratch audit'))
sys.modules['requests']=requests
for name,path in [('RBX_AUDIT',root),('RBX_AUDIT.functions',root/'functions'),('RBX_AUDIT.func_import_v2',root/'func_import_v2'),('RBX_AUDIT.oauth',root/'oauth'),('RBX_AUDIT.oauth.lib',root/'oauth/lib')]:
 mod=types.ModuleType(name);mod.__path__=[str(path)];sys.modules[name]=mod

def load(name,rel):
 spec=importlib.util.spec_from_file_location(name,root/rel);m=importlib.util.module_from_spec(spec);sys.modules[name]=m;spec.loader.exec_module(m);return m
load('RBX_AUDIT.glob_vars','glob_vars.py')
props=load('RBX_AUDIT.props','props.py')
bpy.utils.register_class(props.PROPERTIES_RBX)
bpy.types.Scene.rbx_prefs=bpy.props.PointerProperty(type=props.PROPERTIES_RBX)
modules={}
for rel in ['functions/ugc_bounds.py','functions/dmy_lc_buttons.py','functions/ugc_templates.py','functions/avatar_buttons.py','functions/attach_parent.py','functions/hair_buttons.py','functions/cam_staging.py']:
 mod=load('RBX_AUDIT.'+rel[:-3].replace('/','.'),rel);modules[pathlib.Path(rel).stem]=mod
 for obj in vars(mod).values():
  if isinstance(obj,type) and issubclass(obj,bpy.types.Operator) and obj is not bpy.types.Operator: bpy.utils.register_class(obj)
bpy.types.Object.rbx_fluff=bpy.props.FloatProperty(update=modules['ugc_templates'].fluff_update)
check=load('RBX_AUDIT.oauth.lib.check_animation_operator','oauth/lib/check_animation_operator.py')
bpy.utils.register_class(check.RBX_OT_check_animation_emote)
export=load('RBX_AUDIT.oauth.lib.export_fbx','oauth/lib/export_fbx.py')
kfs=load('RBX_AUDIT.func_import_v2.rbx_build_keyframesequence','func_import_v2/rbx_build_keyframesequence.py')
results=[]
def test(name,fn):
 try: results.append({'check':name,'status':'PASS','measurements':fn()})
 except Exception as e: results.append({'check':name,'status':'FAIL','error':repr(e),'traceback':traceback.format_exc()})
def clear():
 for o in list(bpy.data.objects): bpy.data.objects.remove(o,do_unlink=True)
 for c in list(bpy.data.collections): bpy.data.collections.remove(c)
def selected(o):
 bpy.ops.object.select_all(action='DESELECT');o.select_set(True);bpy.context.view_layer.objects.active=o

def library():
 with bpy.data.libraries.load(str(root/'RBX_Templates.blend'),link=False) as (src,dst): names={k:list(getattr(src,k)) for k in ['collections','objects','materials','actions','particles']}
 (out/'template-inventory.json').write_text(json.dumps(names,indent=2))
 return {k:len(v) for k,v in names.items()}
test('template library readable without autoexec',library)

def bounds():
 clear();bpy.context.scene.rbx_prefs.rbx_bnds_enum='OP1';bpy.context.scene.rbx_prefs.rbx_bnds_hide=True
 r=bpy.ops.object.button_bnds(bnds='UGC');obs=[{'name':o.name,'type':o.type,'dimensions':list(o.dimensions)} for o in bpy.data.objects]
 assert r=={'FINISHED'} and obs
 return {'operator_result':list(r),'objects':obs,'authority':'Reference templates; NOT current Roblox acceptance bounds'}
test('append Hat bounds',bounds)

def cage():
 clear();bpy.context.scene.rbx_prefs.rbx_lc_dum_enum='OP1'
 r=bpy.ops.object.rbx_button_lc(rbx_lc='_Cage')
 meshes=[{'name':o.name,'vertices':len(o.data.vertices),'uv_layers':len(o.data.uv_layers)} for o in bpy.data.objects if o.type=='MESH']
 assert r=={'FINISHED'} and meshes
 return {'operator_result':list(r),'meshes':meshes}
test('append default mannequin cages',cage)

def chain():
 clear();r=bpy.ops.object.rbx_ugc_template(action='chain_1')
 meshes=[{'name':o.name,'vertices':len(o.data.vertices),'modifiers':[m.type for m in o.modifiers]} for o in bpy.data.objects if o.type=='MESH']
 assert r=={'FINISHED'} and meshes
 return {'operator_result':list(r),'meshes':meshes}
test('append Chain 1',chain)

def facs():
 clear();bpy.ops.mesh.primitive_uv_sphere_add(segments=12,ring_count=8);o=bpy.context.object;o.name='Head_Geo';selected(o)
 before=len(o.data.shape_keys.key_blocks) if o.data.shape_keys else 0
 r=bpy.ops.object.rbx_button_ava(rbx_ava='add_facs')
 assert o['Frame0']=='Neutral' and o['Frame24']=='LeftEyeClosed'
 return {'operator_result':list(r),'frame_declarations':len([k for k in o.keys() if k.startswith('Frame')]),'RootFaceJoint':o['RootFaceJoint'],'shape_keys_before':before,'shape_keys_after':len(o.data.shape_keys.key_blocks) if o.data.shape_keys else 0,'bones_created':sum(o.type=='ARMATURE' for o in bpy.data.objects),'deformation_validation':'NOT_CHECKED'}
test('FACS button only declares properties',facs)

def attach():
 clear();bpy.ops.mesh.primitive_cube_add(location=(1,2,3));a=bpy.context.object;a.name='OriginalAccessory'
 bpy.ops.mesh.primitive_cube_add(location=(4,0,0));b=bpy.context.object;b.name='TargetMesh';selected(a)
 old=a.matrix_world.copy();bpy.context.scene.rbx_prefs.rbx_attach_target=b
 r=bpy.ops.object.rbx_attach_to_mesh();err=max(abs(a.matrix_world[i][j]-old[i][j]) for i in range(4) for j in range(4));assert err<1e-5 and a.parent==b
 return {'operator_result':list(r),'world_matrix_max_error':err,'parent':a.parent.name}
test('mesh parenting preserves world transform',attach)

def weight():
 clear();bpy.ops.object.armature_add(location=(3,0,0));arm=bpy.context.object;arm.name='ScratchRig'
 bpy.ops.mesh.primitive_cube_add(location=(1,2,0));o=bpy.context.object;selected(o)
 extra=o.vertex_groups.new(name='Other');extra.add(range(len(o.data.vertices)),.5,'REPLACE')
 p=bpy.context.scene.rbx_prefs;p.rbx_attach_target=arm;p.rbx_attach_bone='Bone';p.rbx_attach_bone_mode='WEIGHTS'
 old=o.matrix_world.copy();r=bpy.ops.object.rbx_attach_to_bone();err=max(abs(o.matrix_world[i][j]-old[i][j]) for i in range(4) for j in range(4))
 assert err<1e-5 and o.vertex_groups.get('Other') and o.vertex_groups.get('Bone')
 return {'operator_result':list(r),'groups':[g.name for g in o.vertex_groups],'world_matrix_max_error':err,'extra_group_retained':True}
test('bone weight bind retains extra groups warning',weight)

def fbx():
 clear();bpy.ops.mesh.primitive_cube_add();o=bpy.context.object;o.name='OriginalCube';old=o.matrix_world.copy();cols=set(bpy.data.collections)
 p=types.SimpleNamespace(export_scale=.01,bake_anim=False,bake_anim_use_all_bones=False,bake_anim_use_nla_strips=False,bake_anim_use_all_actions=False,bake_anim_force_startend_keying=False,bake_anim_step=1.0,bake_anim_simplify_factor=0.0,add_leaf_bones=False,use_custom_props=True)
 path=out/'original-cube.fbx';export.export_fbx(bpy.context.scene,bpy.context.view_layer,o,path,p)
 assert path.stat().st_size>0 and set(bpy.data.collections)==cols and o.matrix_world==old
 return {'bytes':path.stat().st_size,'sha256':hashlib.sha256(path.read_bytes()).hexdigest(),'temporary_collection_cleaned':True,'source_transform_preserved':True}
test('local OAuth-export helper FBX cleanup (no upload)',fbx)

def speed():
 clear();bpy.ops.object.armature_add();arm=bpy.context.object;selected(arm);pb=arm.pose.bones[0]
 for fr,z in [(1,0),(2,2)]:pb.location=(0,0,z);pb.keyframe_insert(data_path='location',frame=fr)
 bpy.context.scene.render.fps=30;bpy.context.scene.frame_set(7)
 violations,maxspeeds=check.RBX_OT_check_animation_emote._run_speed_check(None,bpy.context)
 assert violations and bpy.context.scene.frame_current==7
 return {'violations':violations,'max_speeds':maxspeeds,'threshold_blender_units_s':check.SPEED_LIMIT,'display_scale':check.RBX_SCALE,'frame_restored':True,'Roblox_validation':'NOT_CHECKED'}
test('emote heuristic detects fast scratch bone',speed)

def luau():
 payload=kfs.emit([(0,{}),(.1,{})],.1,'ScratchClip');(out/'generated-scratch.lua').write_text(payload)
 assert 'old:Destroy()' in payload and 'ServerStorage' in payload
 return {'characters':len(payload),'replaces_same_named_ServerStorage_child':True,'Studio_execution':'NOT_CHECKED'}
test('advanced animation payload generated without executing Studio',luau)

def fur():
 clear();bpy.ops.mesh.primitive_cube_add();o=bpy.context.object;o.name='ScratchFurBase';selected(o)
 r=bpy.ops.object.rbx_ugc_template(action='apply_fur');ps=o.particle_systems.get('RBX Fur');assert ps
 ps.settings.count=5;selected(o)
 before=set(bpy.data.objects);r2=bpy.ops.object.rbx_ugc_template(action='convert_fur_combined')
 meshes=[x.name for x in bpy.data.objects if x not in before and x.type=='MESH']
 assert r2=={'FINISHED'} and not o.particle_systems.get('RBX Fur') and meshes
 return {'apply_result':list(r),'convert_result':list(r2),'new_meshes':meshes,'particle_count':5,'particles_removed':True,'Marketplace_geometry':'NOT_CHECKED'}
test('fur apply and conversion with five scratch instances',fur)

def preview_facs():
 clear();bpy.context.scene.rbx_prefs.rbx_ava_enum='OP1';bpy.ops.object.rbx_button_ava(rbx_ava='avatar')
 arm=next(o for o in bpy.data.objects if o.type=='ARMATURE');selected(arm)
 if not arm.animation_data:arm.animation_data_create()
 arm.animation_data.nla_tracks.new().name='ScratchExistingTrack'
 before=set(bpy.data.objects);r=bpy.ops.object.rbx_button_ava(rbx_ava='add_facs_anim')
 assert set(bpy.data.objects)==before and arm.animation_data.action and arm.animation_data.action.name.startswith('FACS_Animation')
 return {'operator_result':list(r),'action':arm.animation_data.action.name,'nla_tracks_after':len(arm.animation_data.nla_tracks),'temporary_objects_cleaned':True,'face_bones':len(arm.data.bones),'actual_FACS_deformation_and_Roblox_validation':'NOT_CHECKED'}
test('FACS preview applies and removes prior NLA tracks',preview_facs)

report={'schema_version':1,'repository':'https://github.com/Gl2imm/RBX_Toolbox','revision':'83efd4e348537f6e1377ac46d0d677838535507b','addon_version':'7.11.0','tested_at':'2026-10-14','blender_version':bpy.app.version_string,'test_scope':'Reviewed modules registered selectively in an isolated factory startup. Full addon installation/OAuth/online imports/update/Studio publish not executed. All HTTP stubbed to fail.','results':results,'summary':{s:sum(x['status']==s for x in results) for s in ['PASS','FAIL']}}
(out/'smoke-results.json').write_text(json.dumps(report,indent=2));print(json.dumps(report,indent=2))
